using RansomFree.Server;
using RansomFree.Contracts;
var root=Path.Combine("D:\\Codex\\RansomFree\\tests","decoy-service-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
var checks=new List<string>();void Check(bool value,string label){if(!value)throw new Exception(label);checks.Add("PASS: "+label);Console.WriteLine(checks[^1]);}
void Reject(Action action,string label){var denied=false;try{action();}catch(Exception ex)when(ex is ArgumentException or DecoyServiceConflictException or KeyNotFoundException){denied=true;}Check(denied,label);}
var store=new Store(root);Check(!store.HasDecoyServiceStorage()&&store.DecoyServices().Count==0,"unconfigured adapter creates no resource");store.InitializeDecoyServiceStorage();
var request=new DecoyServiceChange("Payroll archive","Synthetic fixture; no real records",false,0,"unused"){RequestId=Guid.NewGuid().ToString("N")};
Reject(()=>store.CreateDecoyService(request with{Enabled=true},"fixture"),"creation cannot auto-enable listener resource");
var created=store.CreateDecoyService(request,"fixture");var id=created.Service.Id;var key=created.ActivationPath.Split('/')[^1];
Check(!created.Service.Enabled&&key.Length==64&&!created.AlreadyExists,"creation returns disabled service and one-time activation URL");
var repeated=store.CreateDecoyService(request,"fixture");Check(repeated.AlreadyExists&&repeated.ActivationPath==""&&store.DecoyServices().Count==1,"retries do not duplicate resource or disclose activation secret");
Reject(()=>store.CreateDecoyService(request with{Name="different"},"fixture"),"request identity cannot change content");
Check(!store.TouchDecoyService(id,key,"127.0.0.1","GET"),"disabled resource cannot record a successful service access");
var active=store.ChangeDecoyService(id,request with{Enabled=true,ExpectedRevision=1},"fixture");Check(active.Enabled&&active.Revision==2,"explicit activation creates working service state");
Check(!store.TouchDecoyService(id,new string('0',64),"127.0.0.1","GET"),"incorrect token rejected");
Check(!store.TouchDecoyService(id,key,"127.0.0.1","POST"),"credential/body submission method not processed");
Check(store.TouchDecoyService(id,key,"127.0.0.1","GET"),"valid activation stores real touch evidence");
store=new Store(root);Check(store.DecoyServices().Single().Enabled&&store.DecoyServiceHits(id).Count==1,"service and evidence survive reopen");
Reject(()=>store.ChangeDecoyService(id,request with{ExpectedRevision=1},"fixture"),"stale control cannot change resource");
var disabled=store.ChangeDecoyService(id,request with{ExpectedRevision=2},"fixture");Check(!store.TouchDecoyService(id,key,"127.0.0.1","GET")&&store.DecoyServiceHits(id).Count==1,"rollback to disabled preserves existing evidence");
var repaired=store.ChangeDecoyService(id,request with{Enabled=true,ExpectedRevision=disabled.Revision},"fixture");Check(repaired.Enabled&&store.TouchDecoyService(id,key,"127.0.0.1","GET"),"reactivation repairs disabled route without changing token identity");
var retired=store.ChangeDecoyService(id,request with{ExpectedRevision=repaired.Revision,Name="Retired renamed archive"},"fixture",true);Check(retired.Retired&&!retired.Enabled&&!store.TouchDecoyService(id,key,"127.0.0.1","GET"),"retirement removes route availability and preserves tombstone");
Reject(()=>store.ChangeDecoyService(id,request with{Enabled=true,ExpectedRevision=retired.Revision},"fixture"),"retired token cannot be reactivated");
Check(store.DecoyServiceHits(id).Count==2,"retirement preserves all hit evidence");
Check(store.ManagementAudit().Count(x=>x.Action.StartsWith("Decoy service",StringComparison.Ordinal))==5,"each committed lifecycle change has transactional audit");
var saved=store.ServiceEvents(0);Check(saved.Count==2&&saved.All(x=>x.Event.ServiceContext?.Name=="Payroll archive"&&x.Event.User==null&&x.Event.ProcessId==null),"immutable service context survives rename and never invents an actor");
var endpoint=store.Enroll(new(store.CreateCode().Code,"fixture","fixture"))!;
Reject(()=>store.Ingest(endpoint.EndpointId,new([saved[0].Event])),"endpoint cannot impersonate server-generated service evidence");
store.Ingest(endpoint.EndpointId,new([new(Guid.NewGuid().ToString("N"),DateTimeOffset.UtcNow,"Read","/synthetic",null,null,null,"fixture")]));
var first=await store.History(new(){Limit=1,Sort="sequence",Direction="asc"});Check(first.Items.Count==1&&first.Items[0].Sequence<0&&first.Next!=null,"unified history includes namespaced service events");
var extra=store.CreateDecoyService(request with{RequestId=Guid.NewGuid().ToString("N")},"fixture");store.ChangeDecoyService(extra.Service.Id,request with{ExpectedRevision=1,Enabled=true},"fixture");store.TouchDecoyService(extra.Service.Id,extra.ActivationPath.Split('/')[^1],"127.0.0.1","GET");
var entries=first.Items.ToList();var cursor=first.Next;while(cursor!=null){var page=await store.History(new(){Limit=1,Sort="sequence",Direction="asc"},first.Snapshot,cursor,serviceSnapshot:first.ServiceSnapshot);entries.AddRange(page.Items);cursor=page.Next;}
Check(entries.Count==3&&entries.Select(x=>x.Event.EventId).Distinct().Count()==3&&entries.Count(x=>x.Sequence<0)==2,"two-stream snapshot excludes late service arrivals without duplicates");
var serviceOnly=await store.History(new(){Source="Server service decoy"});Check(serviceOnly.Items.Count==3&&serviceOnly.Items.All(x=>!new HistoryEvent(x.Sequence,x.EndpointId,x.ReceivedUtc,x.Event,EventActivity.From(x.Event)).ResponseCandidate),"server source filtering never offers a process response");
Check(store.Events(0,100).Count==1,"legacy endpoint relay feed excludes server hits");
var serviceSequence=-saved[0].Sequence;var endpointSequence=store.Events(0,100).Single().Sequence;
Check(store.EvidenceRecord(serviceSequence)?.Event.EventId==saved[0].Event.EventId&&store.EvidenceRecord(endpointSequence)?.EndpointId==endpoint.EndpointId,"evidence lookup preserves separate service and endpoint identities");
Check(store.CreateIncident(new("Invalid","Medium",0),"fixture")==null&&store.CreateIncident(new("Invalid","Medium",long.MinValue),"fixture")==null,"invalid signed evidence identities cannot create incidents");
var incident=store.CreateIncident(new("Service investigation","High",serviceSequence),"fixture")!;
Check(incident!=null&&store.IncidentDetails(incident.Id)!.EventSequences.SequenceEqual([serviceSequence]),"incident can start from service evidence");
Check(store.LinkIncidentEvent(incident!.Id,new(1,endpointSequence),"fixture"),"incident can link endpoint evidence alongside service evidence");
Check(!store.LinkIncidentEvent(incident.Id,new(1,-saved[1].Sequence),"fixture"),"stale incident version cannot link service evidence");
Check(!store.LinkIncidentEvent(incident.Id,new(2,serviceSequence),"fixture")&&store.IncidentDetails(incident.Id)!.Incident.Version==2,"duplicate service link rolls back version change");
store=new Store(root);var detail=store.IncidentDetails(incident.Id)!;
Check(detail.EventSequences.Count==2&&detail.EventSequences.Contains(serviceSequence)&&detail.EventSequences.Contains(endpointSequence),"mixed incident links survive store reopen without identifier collision");
Check(detail.EventSequenceTexts.Contains(serviceSequence.ToString(System.Globalization.CultureInfo.InvariantCulture)),"incident evidence exposes exact decimal identifiers for browser clients");
Check(store.EvidenceRecord(long.MinValue)==null&&store.EvidenceRecord(0)==null&&store.EvidenceRecord(-long.MaxValue)==null,"invalid and missing evidence lookups return no record");
var metadataRequest=request with{RequestId=Guid.NewGuid().ToString("N"),Location="Finance lab",Note="Synthetic\nSecond line"};
var metadataService=store.CreateDecoyService(metadataRequest,"fixture");
var metadataActive=store.ChangeDecoyService(metadataService.Service.Id,metadataRequest with{Location=null,Note=null,Enabled=true,ExpectedRevision=1},"fixture");
Check(metadataActive.Location=="Finance lab"&&metadataActive.Note=="Synthetic\nSecond line","older update clients preserve omitted location and note");
var beforeMetadata=store.LatestServiceSequence();store.TouchDecoyService(metadataService.Service.Id,metadataService.ActivationPath.Split('/')[^1],"127.0.0.1","GET");
var metadataCleared=store.ChangeDecoyService(metadataService.Service.Id,metadataRequest with{Location="",Note="",ExpectedRevision=metadataActive.Revision},"fixture");
Check(metadataCleared.Location==""&&metadataCleared.Note==""&&store.ServiceEvents(beforeMetadata).Single().Event.ServiceContext is {Location:"Finance lab",Note:"Synthetic\nSecond line"},"explicit metadata clearing never rewrites prior hit context");
Reject(()=>store.CreateDecoyService(metadataRequest with{RequestId=Guid.NewGuid().ToString("N"),Location="bad\nlocation"},"fixture"),"location rejects control characters");
Reject(()=>store.CreateDecoyService(metadataRequest with{RequestId=Guid.NewGuid().ToString("N"),Note=new string('x',2001)},"fixture"),"note length limit enforced");
await Task.Delay(20); // Keep this snapshot's exclusive end later than the fixture's newest receive timestamp.
var report=store.CreateReport(1,"fixture");
Check(report.Snapshot.ServiceEvents==store.LatestServiceSequence()&&report.Snapshot.Events==1&&report.Snapshot.ReportingEndpoints==1&&report.Snapshot.TotalEvents==report.Snapshot.Events+report.Snapshot.ServiceEvents,"report includes service hits without adding fictitious endpoints");
store=new Store(root);Check(store.ReadReport(report.Id,"fixture",false)!.Snapshot.ServiceEvents==report.Snapshot.ServiceEvents,"saved service counts survive reopen");
var historical=report.Snapshot with{ServiceEvents=null,PreviousServiceEvents=null};
Check(historical.TotalEvents==historical.Events&&!historical.Scope.Contains("service decoys",StringComparison.Ordinal),"historical snapshots do not acquire an invented service scope");
File.WriteAllLines(Path.Combine(root,"results.txt"),checks);Console.WriteLine(root);Console.WriteLine("SQLite lifecycle only. HTTP/GUI, SQL Server, syslog and native virtual-volume adapters remain separate gates.");
